function persist(){if(whatif)return;clearTimeout(saveTimer);$('saveState').textContent='جارٍ الحفظ…';saveTimer=setTimeout(()=>{if(training)return;const data=study.serialize();const ok=safeStore('session',data);if(study.libraryId){const item=library.find(x=>x.id===study.libraryId);if(item){item.study=data;item.name=$('studyName').value||study.headers.Event;item.folder=$('studyFolder').value;item.updated=Date.now();safeStore('library',library)}}if(ok)$('saveState').textContent='محفوظ على هذا الجهاز';},350)}
function settingsValues(){return {time:Number($('engineTime').value),depth:Number($('engineDepth').value),multi:Number($('multiPV').value),hash:Number($('hashSize').value)}}
function isLocked(){if(whatif){say('ارجع للدراسة من تجربة ماذا لو أولًا.');return true;}if(reviewing){say('أوقف تحليل المباراة قبل تعديل الدراسة.');return true}if(training){say('أنهِ التدريب قبل تغيير الدراسة.');return true}return false}
function stopPlay(){if(autoplay){clearInterval(autoplay);autoplay=null;$('playBtn').textContent='▶'}}
async function stopAnalysis(){if(fullDownload){fullDownload.abort();return;}run++;busy=reviewing=false;engine.cancel();board.blocked=false;$('reviewProgress').hidden=true;setBusy(false);try{await engine.start()}catch(e){say(e.message)}}
function setBusy(flag){busy=flag;$('analyzeBtn').disabled=flag;$('reviewBtn').disabled=flag;$('stopBtn').hidden=!flag;board.blocked=reviewing;$('summaryAnalyze').disabled=flag;$('summaryStop').hidden=!flag;$('startGuided').disabled=flag;}
function showView(name){if(whatif&&name!=='analysis')return say('ارجع للدراسة قبل فتح قسم آخر.');if(training&&name!=='analysis')exitTraining();if(name!=='analysis')setGuided(false);document.body.classList.toggle('review-summary',name==='gameReview');view=name;document.body.classList.toggle('home-active',name==='home');$('toolsDialog').close();for(const v of ['home','analysis','library','training','gameReview','radar','repertoire'])$(v+'View').hidden=v!==name;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===name));if(name==='library')renderLibrary();if(name==='training')renderTraining();if(name==='radar')renderRadar();if(name==='repertoire')renderRepertoire();}
function tab(name){document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('selected',b.dataset.tab===name);b.setAttribute('aria-selected',String(b.dataset.tab===name));});for(const t of ['moves','insight','opening','notes'])$(t+'Tab').hidden=t!==name;}
async function navigate(n,{auto=true}={}){if(reviewing)return say('التحليل جارٍ. أوقفه للتنقّل.');if(training)return;if(busy)await stopAnalysis();clearTimeout(autoTimer);study.current=n;board.selected=null;render();persist();if(auto&&!whatif&&$('autoAnalyze').checked)autoTimer=setTimeout(analyzeCurrent,350)}
function loadStudy(s){if(isLocked())return;setGuided(false);stopPlay();clearTimeout(autoTimer);if(busy){run++;engine.cancel();engine.start().catch(e=>say(e.message));setBusy(false)}study=s;study.current=s.current||s.root;$('studyName').value=s.headers.Event||'';$('studyFolder').value=library.find(x=>x.id===s.libraryId)?.folder||'';showView('analysis');render();persist()}
function render(){const n=study.current,c=new Chess(n.fen),line=study.mainline(),idx=line.indexOf(n);$('gameNames').textContent=(study.headers.White||'الأبيض')+' × '+(study.headers.Black||'الأسود');$('eventLabel').textContent=study.headers.Event||'دراسة';$('gameDate').textContent=study.headers.Date||'شطرنج قياسي';$('whiteName').textContent=study.headers.White||'الأبيض';$('blackName').textContent=study.headers.Black||'الأسود';$('whiteRating').textContent=study.headers.WhiteElo||'—';$('blackRating').textContent=study.headers.BlackElo||'—';$('resultLabel').textContent=study.headers.Result||'*';$('turnLabel').textContent=c.isCheckmate()?'كش مات':c.isDraw()?'تعادل':(c.turn()==='w'?'دور الأبيض':'دور الأسود')+(c.isCheck()?' · كش':'');$('positionCounter').textContent=idx>=0?'نقلة '+idx+' / '+(line.length-1):'تفرع · '+(study.path().length-1)+' نقلة';$('branchLabel').textContent=n.name|| (idx>=0?'الخط الأساسي':'تفرع تحليلي');$('comment').value=n.comment||'';$('fenOutput').value=n.fen;board.hints=$('showHints').checked;board.best=!training&&$('showArrow').checked?n.evaluation?.pv?.[0]:null;board.render(n);renderMoves();showLines(n.lines||(n.evaluation?[n.evaluation]:[]));renderChart();renderInsight();if(guided)renderGuided();$('libraryCount').textContent=library.length;}
function renderMoves(){
 const root=$('moveTree');root.replaceChildren();
 $('analysisCount').textContent=study.all().filter(n=>n.evaluation).length+' وضعية محلّلة';
 if(!study.root.children.length){const empty=el('div',undefined,'empty');empty.append(el('strong','أول مباراة، أول فكرة.'),el('span','استورد مباراة من حسابك، أو ابدأ بالمثال.'));const b=el('button','جرّب مباراة توضيحية');b.onclick=()=>$('demoBtn').click();empty.append(b);root.append(empty);return;}
 let currentButton;
 function button(n){const g=grade(n),b=el('button',undefined,(g?.key||'')+(n===study.current?' current':''));b.append(el('span',n.move.san+(g?.key==='blunder'?' ??':g?.key==='mistake'?' ?':'')),el('span',n.evaluation?formatScore(n.evaluation):'','move-eval'));b.title=n.move.san+(g?' · '+g.name:'');b.setAttribute('aria-label',n.parent.fen.split(' ')[5]+' '+b.title);if(n===study.current){b.setAttribute('aria-current','step');currentButton=b;}b.onclick=()=>navigate(n);return b;}
 function branch(parent,container,depth=0){if(depth>30)return;let row=null;while(parent.children[0]){const n=parent.children[0],f=parent.fen.split(' ');if(!row||f[1]==='w'){row=el('div',undefined,'move-row');row.append(el('span',f[5],'moveNo'));if(f[1]==='b')row.append(el('span'));container.append(row);}row.append(button(n));if(n.comment){container.append(el('span',n.comment,'comment'));row=null;}for(const alt of parent.children.slice(1)){const details=el('details',undefined,'variation');details.open=study.path().includes(alt);details.append(el('summary',alt.name||'تفرع: '+alt.move.san));details.append(button(alt));branch(alt,details,depth+1);container.append(details);row=null;}parent=n;}}
 branch(study.root,root);if(currentButton){const top=currentButton.offsetTop-root.offsetTop;if(top<root.scrollTop||top>root.scrollTop+root.clientHeight-40)root.scrollTop=Math.max(0,top-100);}
}
function showLines(lines){latestLines=lines;const first=lines[0];$('mainScore').textContent=formatScore(first);$('evalBarText').textContent=formatScore(first);$('evalFill').style.height=(first?Math.max(2,Math.min(98,winning(first))):50)+'%';$('depthMetric').textContent='عمق '+(first?.depth||'—');$('speedMetric').textContent=first?.nps?(first.nps/1000).toFixed(0)+' kN/s':'— kN/s';$('nodesMetric').textContent=first?.nodes?(first.nodes/1000).toFixed(0)+'k عقدة':'— عقدة';$('timeMetric').textContent=first?.time?(first.time/1000).toFixed(1)+' ث':'— ث';paintSmart(lines);if(!busy)$('stabilityMetric').textContent=first?'نتيجة محفوظة · '+(first.time? (first.time/1000).toFixed(1)+' ث':'وضعية نهائية'):'بانتظار التحليل';const box=$('engineLines');box.replaceChildren();if(!lines.length){box.append(el('p','أفضل الاستمرارات ستظهر هنا. شغّل المحرك لبدء التحليل.','empty'));return}const fen=study.current.fen;for(const e of lines){const row=el('div',undefined,'engineLine');row.append(el('strong',formatScore(e)));const moves=el('div');pvSAN(fen,e.pv).slice(0,10).forEach((m,i)=>{const b=el('button',m.label);b.title='جرّب هذا الخط حتى '+m.san;b.onclick=()=>playPV(e.pv.slice(0,i+1));b.onmouseenter=()=>previewPV(fen,e.pv.slice(0,i+1),b);b.onfocus=()=>previewPV(fen,e.pv.slice(0,i+1),b);b.onmouseleave=b.onblur=()=>{$('pvPreview').hidden=true;};moves.append(b)});if(!e.pv.length)moves.append(el('span',e.terminal==='draw'?'تعادل':'كش مات'));row.append(moves);box.append(row)}board.best=!training&&$('showArrow').checked?first?.pv?.[0]:null;board.renderArrows()}
function renderChart(){const svg=$('evalChart'),line=study.mainline(),ns='http://www.w3.org/2000/svg';svg.replaceChildren();const add=(tag,attrs)=>{const e=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));svg.append(e);return e};add('line',{x1:0,y1:45,x2:600,y2:45,stroke:'#c4d5e1','stroke-dasharray':'4 4'});let path='';line.forEach((n,i)=>{if(!n.evaluation){path+=' ';return}const x=8+i/Math.max(1,line.length-1)*584,y=83-winning(n.evaluation)/100*76;const prev=line[i-1]?.evaluation;path+=(prev?' L':' M')+x+','+y;const circle=add('circle',{cx:x,cy:y,r:5,fill:['mistake','blunder'].includes(grade(n)?.key)?'#ef6b65':'transparent',class:'chartPoint',tabindex:'0',role:'button','aria-label':'الوضعية '+i+' '+formatScore(n.evaluation)});circle.onclick=()=>navigate(n);circle.onkeydown=e=>{if(e.key==='Enter')navigate(n)}});if(path.trim())svg.insertBefore(Object.assign(document.createElementNS(ns,'path'),{}),svg.firstChild);const p=svg.querySelector('path');if(p){p.setAttribute('d',path);p.setAttribute('fill','none');p.setAttribute('stroke','#3686ba');p.setAttribute('stroke-width','2')}const idx=line.indexOf(study.current);if(idx>=0)add('line',{x1:8+idx/Math.max(1,line.length-1)*584,x2:8+idx/Math.max(1,line.length-1)*584,y1:3,y2:87,stroke:'#54a88e','stroke-width':1});const count=line.filter(n=>n.evaluation).length;$('chartCaption').textContent=count?count+' / '+line.length+' وضعية · اضغط للتنقّل':'حلّل المباراة لإظهار المنحنى';}
function renderInsight(){const n=study.current,g=grade(n);$('moveGrade').textContent=g?.name||'افهم الفكرة';$('moveGrade').className=g?.key||'';$('explanation').textContent=explanation(n)+' '+tacticalFacts(n).join(' ');$('comparison').textContent=n.parent?.evaluation?'نقلتك: '+n.move.san+' · التقييم بعدها: '+formatScore(n.evaluation)+' | البديل: '+(pvSAN(n.parent.fen,n.parent.evaluation.pv)[0]?.san||'—')+' · التقييم قبله: '+formatScore(n.parent.evaluation):'سيظهر الفرق بين نقلتك والبديل بعد تحليل الوضعيتين.';const line=study.mainline().slice(1),counts=Object.fromEntries(CATEGORIES.map(c=>[c.key,0]));line.forEach(n=>{const g=grade(n);if(g)counts[g.key]++});$('reportSummary').replaceChildren(el('strong','ملخّص الدراسة'),el('p',`Brilliant: ${counts.brilliant} · Great: ${counts.great} · Excellent: ${counts.excellent} · Best: ${counts.best} · Good: ${counts.good} · Inaccuracy: ${counts.inaccuracy} · Mistake: ${counts.mistake} · Blunder: ${counts.blunder}`));const critical=line.filter(n=>['mistake','blunder'].includes(grade(n)?.key)).sort((a,b)=>grade(b).loss-grade(a).loss).slice(0,3);critical.forEach(n=>{const b=el('button','راجع '+n.move.san+' — النقلة '+n.parent.fen.split(' ')[5]);b.onclick=()=>navigate(n);$('reportSummary').append(b)});}
async function analyzeCurrent(){if(busy||training)return;if(whatif&&!whatif.revealed)return say('اكتب خطك ثم استخدم اكشف وقارن الحساب.');if(!engine.ready)return say('انتظر جاهزية المحرك أو استعد النسخة المدمجة من الإعدادات.');stopPlay();const n=study.current,id=++run;setBusy(true);document.querySelector('.engine-details').open=true;say('جارٍ تحليل الوضعية الحالية…');let prev=null,stable=0,lastDepth=-1;try{const lines=await engine.analyze(n.fen,{...settingsValues(),onInfo:lines=>{if(id!==run)return;const f=lines[0];if(f&&f.depth>lastDepth){if(f.pv?.[0]===prev)stable++;else{prev=f.pv?.[0];stable=0}lastDepth=f.depth}showLines(lines);$('stabilityMetric').textContent=stable>=3?'الاختيار ثابت مؤخرًا':'البحث يتطوّر…'}});if(id!==run)return;n.lines=lines;n.evaluation=lines[0]||null;n.search={...settingsValues(),engine:engine.name};render();persist();say('اكتمل تحليل الوضعية. الأرقام من منظور الأبيض.')}catch(e){if(id===run)say(e.message)}finally{if(id===run)setBusy(false)}}
async function review(){if(busy||training)return;if(whatif)return say('استخدم مقارنة الحساب داخل تجربة ماذا لو.');if(!engine.ready)return say('انتظر جاهزية المحرك');if(!study.root.children.length){say('استورد مباراة أولًا، ثم اضغط حلّل المباراة.');return openImport();}stopPlay();const id=++run;reviewing=true;setBusy(true);$('reviewProgress').value=0;$('reviewProgress').hidden=false;say('بدأ تحليل المباراة. يمكنك إيقافه مع الاحتفاظ بالنتائج.');const line=study.mainline(),opts=settingsValues();try{for(let i=0;i<line.length;i++){if(id!==run)return;const n=line[i];const sufficient=n.evaluation&&n.search?.engine===engine.name&&n.search.multi>=2&&(opts.depth?n.evaluation.depth>=opts.depth:(!n.search.depth&&n.search.time>=opts.time));if(!sufficient){const result=await engine.analyze(n.fen,{...opts,multi:2});n.lines=result;n.evaluation=result[0]||null;n.search={...opts,multi:2,engine:engine.name};}if(id!==run)return;$('reviewProgress').value=(i+1)/line.length*100;say('تحليل الوضعية '+(i+1)+' من '+line.length);renderMoves();renderChart();persist();}if($('deepCritical').checked){const targets=line.filter(n=>['mistake','blunder'].includes(grade(n)?.key)).slice(0,12);for(let i=0;i<targets.length;i++){say('تدقيق اللحظة الحرجة '+(i+1)+' من '+targets.length);for(const n of [targets[i].parent,targets[i]]){const result=await engine.analyze(n.fen,{...opts,depth:0,time:Math.max(4000,opts.time*2),multi:2,useCache:false});if(id!==run)return;n.lines=result;n.evaluation=result[0]||null;n.search={...opts,depth:0,time:Math.max(4000,opts.time*2),multi:2,engine:engine.name};}persist()}}render();tab('insight');persist();extractAllMistakes(true);queueMicrotask(showReviewOverview);say('اكتمل تحليل المباراة. الملخّص جاهز؛ ابدأ المراجعة نقلة بنقلة.')}catch(e){if(id===run)say(e.message)}finally{if(id===run){reviewing=false;setBusy(false);$('reviewProgress').hidden=true}}}
async function makeMove(from,to){if(reviewing)return;const c=new Chess(study.current.fen),legal=c.moves({square:from,verbose:true}).filter(m=>m.to===to);if(!legal.length){board.render(study.current);return}let promotion;if(legal.some(m=>m.promotion)){promotion=await choosePromotion(c.turn());if(!promotion)return}const uci=from+to+(promotion||'');if(training)return answerPuzzle(uci);if(busy)await stopAnalysis();study.play({from,to,promotion});render();persist();if(!whatif&&$('autoAnalyze').checked)autoTimer=setTimeout(analyzeCurrent,350)}
function choosePromotion(color){return new Promise(resolve=>{const box=$('promotionOptions');box.replaceChildren();const done=v=>{$('promotionDialog').close();resolve(v)};for(const type of ['q','r','b','n']){const b=el('button');const img=el('img');img.src=imgPath({color,type});img.alt=type;b.append(img);b.onclick=()=>done(type);box.append(b)}$('cancelPromotion').onclick=()=>done(null);$('promotionDialog').oncancel=e=>{e.preventDefault();done(null)};$('promotionDialog').showModal()})}
async function playPV(pv){if(isLocked())return;if(busy)await stopAnalysis();for(const move of pv){try{study.play(move)}catch{break}}render();persist();say('أضيف الاستمرار كتفرع قابل للتحرير.')}
function saveLibrary(){if(training||whatif)return;const id=study.libraryId||crypto.randomUUID();study.libraryId=id;const item={id,name:$('studyName').value.trim()||study.headers.Event||'دراسة',folder:$('studyFolder').value.trim(),updated:Date.now(),study:study.serialize()};const i=library.findIndex(x=>x.id===id);if(i<0)library.unshift(item);else library[i]=item;safeStore('library',library);persist();$('libraryCount').textContent=library.length;say('حُفظت الدراسة والتفرعات والملاحظات في مكتبتك.');}
function renderLibrary(){const query=$('librarySearch').value.toLowerCase(),folder=$('folderFilter').value,sort=$('librarySort').value;const folders=[...new Set(library.map(x=>x.folder).filter(Boolean))];$('folderFilter').replaceChildren(el('option','كل المجلدات'));$('folderFilter').firstChild.value='';folders.forEach(f=>{const o=el('option',f);o.value=f;$('folderFilter').append(o)});$('folderFilter').value=folder;let rows=library.filter(x=>(!folder||x.folder===folder)&&JSON.stringify([x.name,x.folder,x.study.headers]).toLowerCase().includes(query));rows.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='date'?String(b.study.headers.Date||'').localeCompare(String(a.study.headers.Date||'')):b.updated-a.updated);$('libraryRows').replaceChildren();rows.forEach(item=>{const h=item.study.headers,tr=el('tr');let s;try{s=Study.restore(item.study)}catch{return}const total=s.mainline().length,done=s.mainline().filter(n=>n.evaluation).length;for(const t of [item.name,h.White||'—',h.Black||'—',h.Result||'*',h.Date||'—',item.folder||'—',done+'/'+total])tr.append(el('td',t));const td=el('td'),open=el('button','فتح'),remove=el('button','حذف');open.onclick=()=>loadStudy(s);remove.onclick=()=>{if(!confirm('حذف هذه الدراسة من المكتبة؟'))return;library=library.filter(x=>x.id!==item.id);if(study.libraryId===item.id)study.libraryId=null;safeStore('library',library);renderLibrary();$('libraryCount').textContent=library.length;};td.append(open,remove);tr.append(td);$('libraryRows').append(tr)});$('libraryEmpty').hidden=rows.length>0;$('libraryTotal').textContent=rows.length+' دراسة';}
function openImport(){if(isLocked())return;$('toolsDialog').close();$('importDialog').showModal()}
function listImports(raws){const box=$('importResults');box.replaceChildren();let valid=0;raws.forEach(raw=>{try{const s=Study.parse(raw),h=s.headers;if(h.Result==='*'&&(h.Site||'').includes('lichess.org'))return;const b=el('button',(h.White||'الأبيض')+' × '+(h.Black||'الأسود'));b.append(el('small',(h.Date||'')+' · '+h.Result+' · '+(s.mainline().length-1)+' نقلة'));b.onclick=()=>{selectHomeStudy(s);$('importDialog').close()};box.append(b);valid++}catch{}});$('importStatus').textContent=valid?'وجدنا '+valid+' مباراة. اختر مباراة لفتحها وحفظها.':'لم نجد مباريات قياسية صالحة مطابقة.';if(valid>1){const b=el('button','حفظ جميع المباريات في المكتبة','primary');b.onclick=()=>{let added=0;for(const raw of raws){try{const s=Study.parse(raw);if(library.some(x=>x.study.headers.Site&&x.study.headers.Site===s.headers.Site&&s.headers.Site!=='?'))continue;const id=crypto.randomUUID();s.libraryId=id;library.unshift({id,name:s.headers.Event||'مباراة',folder:'مستوردة',updated:Date.now(),study:s.serialize()});added++}catch{}}safeStore('library',library);$('importDialog').close();showView('library');$('libraryCount').textContent=library.length;say('تم حفظ '+added+' مباراة.');};box.prepend(b)}}
async function importRaw(raw){if(raw.length>8e6)return say('الملف أكبر من 8 ميجابايت. قسّمه لملفات أصغر.');const raws=splitPGN(raw);if(raws.length===1){try{const parsed=Study.parse(raw);$('importDialog').close();await selectHomeStudy(parsed)}catch(e){$('importStatus').textContent=e.message}}else listImports(raws);}
async function fetchAccount(){const b=$('fetchBtn');b.disabled=true;$('importResults').replaceChildren();try{const raws=await importGames({platform,username:$('username').value,from:$('fromDate').value,to:$('toDate').value,color:$('colorFilter').value,speed:$('speedFilter').value},s=>$('importStatus').textContent=s);safeStore('account-'+platform,$('username').value);listImports(raws)}catch(e){$('importStatus').textContent=e instanceof TypeError?'الاتصال بالخدمة غير متاح من المتصفح. جرّب لاحقًا أو ارفع ملف PGN.':e.message}finally{b.disabled=false}}
function savePuzzle(n=study.current){const start=n.parent||n;if(!start.evaluation?.pv?.length)return say('حلّل الوضعية السابقة أولًا ليكون للتمرين حل مسجّل.');if(puzzles.some(p=>p.fen===start.fen))return say('هذه الوضعية موجودة في تدريبك بالفعل.');puzzles.push({id:crypto.randomUUID(),fen:start.fen,solution:start.evaluation.pv[0],pv:start.evaluation.pv,title:(study.headers.White||'الأبيض')+' × '+(study.headers.Black||'الأسود'),sourceMove:n.move?.san||'',created:Date.now(),due:Date.now(),solved:0,attempts:0,interval:0});safeStore('puzzles',puzzles);say('حُفظت الوضعية في تدريبك.');}
function renderTraining(){const due=puzzles.filter(p=>p.due<=Date.now()).length,solved=puzzles.reduce((s,p)=>s+p.solved,0);$('trainingStats').replaceChildren();for(const [label,value] of [['التمارين',puzzles.length],['للمراجعة اليوم',due],['إجابات صحيحة',solved]]){const d=el('div',label);d.append(el('strong',String(value)));$('trainingStats').append(d)}$('puzzleRows').replaceChildren();if(!puzzles.length){$('puzzleRows').append(el('p','حلّل مباراة، ثم استخرج الأخطاء كتمارين أو احفظ وضعية من تبويب «الفهم».','empty'));return}puzzles.slice().sort((a,b)=>a.due-b.due).forEach(p=>{const row=el('div',undefined,'puzzlerow'),name=el('div',p.title);name.append(el('small',(p.fen.split(' ')[1]==='w'?'الأبيض':'الأسود')+' يلعب · '+(p.due<=Date.now()?'جاهزة للمراجعة':'المراجعة: '+new Date(p.due).toLocaleDateString('ar-EG'))+' · المحاولات '+p.attempts));const controls=el('div'),start=el('button','تدرّب','primary'),remove=el('button','حذف');start.onclick=()=>startPuzzle(p);remove.onclick=()=>{if(!confirm('حذف التمرين؟'))return;puzzles=puzzles.filter(x=>x.id!==p.id);safeStore('puzzles',puzzles);renderTraining()};controls.append(start,remove);row.append(name,controls);$('puzzleRows').append(row)});}
async function baseStartPuzzle(p){if(!clinicReady)return say('انتظر فتح قاعدة العيادة.');if(reviewing)return say('أوقف التحليل أولًا.');if(busy)await stopAnalysis();stopPlay();clearTimeout(saveTimer);safeStore('session',study.serialize());returnStudy=study;training={p,hints:0,done:false};study=new Study(p.fen);study.headers.Event='تمرين من مبارياتك';board.selected=null;showView('analysis');document.body.classList.add('trainingMode');$('trainingBanner').hidden=false;$('trainingQuestion').textContent=(p.fen.split(' ')[1]==='w'?'الأبيض':'الأسود')+' يلعب. ما اختيارك؟';$('trainingFeedback').textContent='';board.best=null;render();}
function answerPuzzle(uci){if(!training||training.done)return;const p=training.p;p.attempts++;if(uci===p.solution){p.solved++;p.interval=training.hints?1:Math.min(60,p.interval?Math.max(2,p.interval*2):1);p.due=Date.now()+p.interval*86400000;training.done=true;study.play(uci);render();$('trainingFeedback').textContent='صحيح! راجع الفكرة بعد '+p.interval+' يوم.';}else{p.interval=0;p.due=Date.now()+600000;training.hints++;$('trainingFeedback').textContent='اختيارك مختلف عن الحل المسجّل. جرّب مرة أخرى أو اطلب تلميحًا.';board.render(study.current)}safeStore('puzzles',puzzles);}
function exitTraining(){clearInterval(clinicInterval);if(!training)return;training=null;document.body.classList.remove('trainingMode');$('trainingBanner').hidden=true;study=returnStudy||new Study();returnStudy=null;render();}
function promptText(title,value,callback){$('textTitle').textContent=title;$('textValue').value=value;$('textSubmit').onclick=()=>{callback($('textValue').value);$('textDialog').close()};$('textDialog').showModal();$('textValue').focus();}
let editorPieces={},editorChoice={type:'p',color:'w'};
function setupEditor(fen=study.current.fen){const c=new Chess(fen);editorPieces={};c.board().flat().filter(Boolean).forEach(p=>editorPieces[p.square]={type:p.type,color:p.color});const f=fen.split(' ');$('editorTurn').value=f[1];$('editorEP').value=f[3];document.querySelectorAll('.castleoptions input').forEach(x=>x.checked=f[2].includes(x.value));renderEditor();}
function renderEditor(){const root=$('editorBoard');root.replaceChildren();for(const r of '87654321')for(const f of 'abcdefgh'){const sq=f+r,b=el('button',undefined,'square'+((f.charCodeAt(0)+Number(r))%2===0?' dark':''));b.setAttribute('aria-label','وضع قطعة على '+sq);const p=editorPieces[sq];if(p){const img=el('img');img.src=imgPath(p);img.alt='';b.append(img)}b.onclick=()=>{if(editorChoice)editorPieces[sq]={...editorChoice};else delete editorPieces[sq];renderEditor()};root.append(b)}}
function editorFen(){const ranks=[];for(const r of '87654321'){let rank='',empty=0;for(const f of 'abcdefgh'){const p=editorPieces[f+r];if(!p){empty++;continue}if(empty){rank+=empty;empty=0}rank+=p.color==='w'?p.type.toUpperCase():p.type;}if(empty)rank+=empty;ranks.push(rank)}const castle=[...document.querySelectorAll('.castleoptions input:checked')].map(x=>x.value).join('')||'-',ep=$('editorEP').value.trim()||'-';return ranks.join('/')+' '+$('editorTurn').value+' '+castle+' '+ep+' 0 1';}
function validateEditor(fen){const c=new Chess(fen);const pieces=c.board().flat().filter(Boolean),w=pieces.find(p=>p.type==='k'&&p.color==='w'),b=pieces.find(p=>p.type==='k'&&p.color==='b');if(!w||!b)throw Error('يلزم ملك لكل جانب.');if(Math.abs(w.square.charCodeAt(0)-b.square.charCodeAt(0))<=1&&Math.abs(Number(w.square[1])-Number(b.square[1]))<=1)throw Error('الملكان لا يمكن أن يكونا متجاورين.');const other=c.turn()==='w'?b:w;if(c.isAttacked(other.square,c.turn()))throw Error('الطرف الذي انتهى دوره لا يجوز أن يكون في كش.');const rights=fen.split(' ')[2],checks={K:['e1','h1','w'],Q:['e1','a1','w'],k:['e8','h8','b'],q:['e8','a8','b']};for(const r of rights){if(!checks[r])continue;const [k,rook,color]=checks[r];if(c.get(k)?.type!=='k'||c.get(k)?.color!==color||c.get(rook)?.type!=='r'||c.get(rook)?.color!==color)throw Error('حقوق التبييت غير متوافقة مع أماكن الملك والرخ.')}return c;}
let openingData=null;
async function localOpening(){if(!openingData)openingData=await fetch(new URL('../assets/openings/openings.json',import.meta.url)).then(r=>r.json());const fen=study.current.fen.split(' ').slice(0,4).join(' '),path=study.path().slice(1).map(n=>n.move.lan).join(' ');return openingData.find(x=>x.epd===fen)||openingData.filter(x=>x.uci&&path.startsWith(x.uci)).sort((a,b)=>b.uci.length-a.uci.length)[0]||null;}
async function showOpening(){const box=$('openingResult'),node=study.current;box.replaceChildren(el('p','جارٍ البحث…'));try{const local=await localOpening();if(study.current!==node)return;box.replaceChildren(el('strong',local?local.eco+' · '+local.name:'لا يوجد اسم مطابق في قاعدة الافتتاح المحلية'));const token=sessionStorage.getItem('tcl-lichess-token');if(!token){box.append(el('p','أسماء الافتتاحات متاحة محليًا. إحصاءات الأساتذة تتطلب تسجيل دخول Lichess حسب واجهة الخدمة الحالية.'));const connect=el('button','ربط Lichess لعرض الإحصاءات');connect.onclick=connectLichess;box.append(connect);return}const params=new URLSearchParams({fen:study.root.fen,play:study.path().slice(1).map(n=>n.move.lan).join(','),moves:'12',topGames:'0'});const r=await fetch('https://explorer.lichess.org/masters?'+params,{headers:{Authorization:'Bearer '+token},signal:AbortSignal.timeout(25000)});if(!r.ok){if(r.status===401)sessionStorage.removeItem('tcl-lichess-token');throw Error('تعذّر جلب الإحصاءات من Lichess ('+r.status+').')}const d=await r.json();if(study.current!==node)return;box.append(el('p','المصدر: قاعدة أساتذة Lichess · '+(d.white+d.draws+d.black).toLocaleString()+' مباراة'));for(const m of d.moves){const b=el('button');b.append(el('strong',m.san),el('span','أبيض '+m.white+' · تعادل '+m.draws+' · أسود '+m.black));b.onclick=()=>playPV([m.uci]);box.append(b)}}catch(e){box.append(el('p',e instanceof TypeError?'الخدمة غير متاحة عبر الاتصال الحالي.':e.message))}}
async function tablebase(){const n=study.current,c=new Chess(n.fen),box=$('openingResult');if(c.board().flat().filter(Boolean).length>7)return say('Tablebase تدعم 7 قطع أو أقل، شامل الملكين.');if(n.fen.split(' ')[2]!=='-')return say('فحص النهايات يتطلب وضعية بلا حقوق تبييت.');box.replaceChildren(el('p','فحص قاعدة النهايات…'));try{const d=await get('https://tablebase.lichess.org/standard?fen='+encodeURIComponent(n.fen));if(study.current!==n)return;const labels={win:'فوز',loss:'خسارة',draw:'تعادل','cursed-win':'فوز نظري يتأثر بقاعدة 50 نقلة','blessed-loss':'خسارة نظرية قد تنقذها قاعدة 50 نقلة',unknown:'غير متاح'};box.replaceChildren(el('strong',(labels[d.category]||d.category)+' للطرف صاحب الدور'),el('p','المصدر: Lichess Tablebase · DTZ '+(d.dtz??'—')+' · المسافة لأخذ قطعة أو تحريك بيدق وفق معيار القاعدة.'));d.moves?.slice(0,12).forEach(m=>{const b=el('button',m.san+' · نتيجة الخصم بعدها: '+(labels[m.category]||m.category));b.onclick=()=>playPV([m.uci]);box.append(b)})}catch(e){box.replaceChildren(el('p','تعذّر فحص النهاية: '+e.message))}}
async function connectLichess(){try{const bytes=crypto.getRandomValues(new Uint8Array(32)),encode=b=>btoa(String.fromCharCode(...b)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');const verifier=encode(bytes),challenge=encode(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier)))),state=crypto.randomUUID(),redirect=new URL('./index.html',location.href).href.split('?')[0];safeStore('session',study.serialize());sessionStorage.setItem('tcl-oauth',JSON.stringify({verifier,state,redirect}));const params=new URLSearchParams({response_type:'code',client_id:'thomas-chess-lab',redirect_uri:redirect,code_challenge:challenge,code_challenge_method:'S256',state,scope:''});location.assign('https://lichess.org/oauth?'+params)}catch{say('تعذّر بدء تسجيل الدخول. يلزم اتصال HTTPS ومتصفح يدعم Web Crypto.')}}
async function finishOAuth(){const q=new URLSearchParams(location.search);if(!q.has('code')&&!q.has('error'))return;const stored=sessionStorage.getItem('tcl-oauth');history.replaceState(null,'',location.pathname);try{const s=JSON.parse(stored||'null');if(!s||q.get('state')!==s.state)throw Error('تعذّر التحقق من طلب تسجيل الدخول.');if(q.has('error'))throw Error('تم إلغاء ربط Lichess.');const r=await fetch('https://lichess.org/api/token',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'authorization_code',code:q.get('code'),code_verifier:s.verifier,redirect_uri:s.redirect,client_id:'thomas-chess-lab'})});if(!r.ok)throw Error('تعذّر إكمال الربط.');const d=await r.json();if(!d.access_token)throw Error('لم يصل تصريح الدخول.');sessionStorage.setItem('tcl-lichess-token',d.access_token);say('تم ربط Lichess لهذه الجلسة. يمكنك عرض إحصاءات الافتتاح.')}catch(e){say(e.message)}finally{sessionStorage.removeItem('tcl-oauth')}}
function printReport(){const box=$('printReport');box.replaceChildren(el('h1','Thomas Chess Lab · تقرير التحليل'),el('h2',study.headers.White+' × '+study.headers.Black),el('p',(study.headers.Event||'')+' · '+(study.headers.Date||'')+' · '+study.headers.Result),el('p','تقييمات Stockfish من منظور الأبيض. التصنيفات تقريبية وليست درجات رسمية من منصات اللعب.'));const table=el('table'),head=el('tr');['النقلة','التقييم','التصنيف','البديل','ملاحظات'].forEach(t=>head.append(el('th',t)));table.append(head);study.mainline().slice(1).forEach(n=>{const tr=el('tr');[n.parent.fen.split(' ')[5]+(n.move.color==='w'?'. ':'… ')+n.move.san,formatScore(n.evaluation),grade(n)?.name||'غير محللة',pvSAN(n.parent.fen,n.parent.evaluation?.pv)[0]?.san||'—',n.comment||''].forEach(t=>tr.append(el('td',t)));table.append(tr)});box.append(table);window.print();}
