function splitter(id,side,min,max){$(id).onpointerdown=e=>{e.preventDefault();$(id).setPointerCapture(e.pointerId);const start=e.clientX,old=parseInt(getComputedStyle(document.documentElement).getPropertyValue('--'+side));$(id).onpointermove=e=>{settings[side]=Math.min(max,Math.max(min,old+(side==='left'?1:-1)*(e.clientX-start)));document.documentElement.style.setProperty('--'+side,settings[side]+'px')};$(id).onpointerup=()=>{$(id).onpointermove=null;safeStore('settings',settings)}}}
