async function bootEngine(){try{if(readStore('engine-choice','lite')==='full'){const files=await fullEngineFiles({cachedOnly:true});if(files){await activateFull(files);return;}}await engine.start(BUILTIN);updateEngineHint(false);}catch(e){say(e.message);try{await engine.start(BUILTIN);updateEngineHint(false);}catch{}}}
