 controller.signal.throwIfAborted();$('cancelFullBtn').hidden=true;$('engineDownloadStatus').textContent='تشغيل شبكة التقييم الكاملة…';await activateFull(files);safeStore('engine-choice','full');$('engineDownloadStatus').textContent='Stockfish 19 Full جاهز. ارجع للرقعة واضغط «حلّل المباراة».';say('Stockfish 19 Full مفعّل. التحليل يستخدم النسخة الكاملة الآن.');
