async function prepareBook(){try{if(!openingData)openingData=await fetch(new URL('../assets/openings/openings.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Opening data unavailable');return r.json()});bookPrefixes=openingPrefixes(openingData);}catch{bookPrefixes=new Set();}}
async function showReviewOverview(){if(whatif)return say('ارجع للدراسة أولًا.');if(training)return say('أنهِ التدريب أولًا.');if(busy)return say('أوقف التحليل أولًا لفتح الملخّص.');stopPlay();clearTimeout(autoTimer);await prepareBook();showView('gameReview');renderOverview();window.scrollTo?.({top:0,behavior:'instant'});}
function renderOverview(){const rows=reviewRows(study,bookPrefixes),stats=reviewStats(rows);$('reviewWhite').textContent=study.headers.White||'الأبيض';$('reviewBlack').textContent=study.headers.Black||'الأسود';for(const [side,id] of [['w','whiteAccuracy'],['b','blackAccuracy']])$(id).textContent=stats[side].accuracy===null?'—':stats[side].accuracy.toFixed(1)+'%';
 const complete=rows.filter(r=>r.score!==null).length;$('reviewCoverage').textContent=complete+' / '+rows.length+' نقلة محلّلة'+(complete<rows.length?' · نتائج جزئية':' · اكتمل تحليل النقلات');
 $('startGuided').disabled=busy||!rows.length;$('continueAnalysis').hidden=!!rows.length&&complete===rows.length;
 const mistakes=rows.filter(r=>['mistake','blunder'].includes(r.key)).length;$('overviewCoach').textContent=!rows.length?'استورد مباراة، وبعدها نراجع قراراتك خطوة بخطوة.':!complete?'المباراة جاهزة. ابدأ التحليل ليظهر التقييم واللحظات المهمة.':mistakes?'عندنا '+mistakes+' لحظة تستحق المراجعة. نعرف البديل ونجرّبه مع بعض؟':'النقلات المحلّلة لا تحتوي على أخطاء كبيرة حسب إعدادات البحث الحالية. نراجع الأفكار مع بعض؟';
 $('categoryRows').replaceChildren();for(const category of CATEGORIES){if(category.key==='pending'&&!stats.w.counts.pending&&!stats.b.counts.pending)continue;const tr=el('tr'),th=el('th'),badge=el('span',category.icon,'grade-badge');badge.style.background=category.color;th.append(badge,el('span',category.name));tr.append(th);for(const side of ['w','b']){const td=el('td'),count=stats[side].counts[category.key],button=el('button',String(count));button.style.color=category.color;button.disabled=!count;button.setAttribute('aria-label',category.name+' · '+(side==='w'?'الأبيض':'الأسود')+' · '+count);button.onclick=()=>startGuided(rows.find(r=>r.side===side&&r.key===category.key)?.node);td.append(button);tr.append(td);}$('categoryRows').append(tr);}
 const graph=$('evalChart').cloneNode(true);graph.removeAttribute('id');graph.setAttribute('aria-label','أفضلية الأبيض عبر المباراة');$('summaryChart').replaceChildren(graph);const analysed=study.mainline().filter(n=>n.evaluation);graph.querySelectorAll('.chartPoint').forEach((point,i)=>{point.onclick=()=>startGuided(analysed[i]);point.onkeydown=e=>{if(e.key==='Enter'||e.key===' ')startGuided(analysed[i]);}});
 const table=el('table'),head=el('tr');['المقياس','الأبيض','الأسود'].forEach(t=>head.append(el('th',t)));table.append(head);for(const [label,values] of [['اكتمال التحليل',[stats.w.done+'/'+stats.w.total,stats.b.done+'/'+stats.b.total]],['متوسط انخفاض مؤشر الفرص',[stats.w.loss?.toFixed(2)??'—',stats.b.loss?.toFixed(2)??'—']],['أخطاء كبيرة',[stats.w.counts.blunder,stats.b.counts.blunder]],['Game Rating · تجريبي',['w','b'].map(side=>estimateGameRating(study.headers[side==='w'?'WhiteElo':'BlackElo'],stats[side].accuracy,stats[side].done===stats[side].total)??'—')]]){const tr=el('tr');tr.append(el('th',label));values.forEach(v=>tr.append(el('td',String(v))));table.append(tr);}$('reviewAdvanced').replaceChildren(table);renderPhaseComparison(rows);renderUnavailableCategories();
}
async function startGuided(node){if(busy||training)return;const target=node?.move?node:study.mainline()[1];if(!target)return openImport();stopPlay();clearTimeout(autoTimer);showView('analysis');setGuided(true);await navigate(target,{auto:false});window.scrollTo?.({top:0,behavior:'instant'});}
function renderGuided(){document.body.classList.remove('showing-alternative');const rows=reviewRows(study,bookPrefixes),row=rows.find(r=>r.node===study.current),index=rows.findIndex(r=>r.node===study.current),category=CATEGORIES.find(c=>c.key===row?.key);$('guidedGrade').textContent=(row?row.node.move.san+' · ':'')+(category?category.icon+' '+category.name:'تفرع تحليلي');$('guidedGrade').style.color=category?.color||'var(--ink)';$('guidedText').textContent=coachText(row);$('guidedEval').textContent=formatScore(study.current.evaluation);$('guidedCounter').textContent=index>=0?'النقلة '+(index+1)+' من '+rows.length:'خارج الخط الأساسي';$('guidedPrev').disabled=index<=0;$('guidedNext').textContent=index===rows.length-1?'الملخّص ✓':'التالي ←';$('guidedBest').disabled=!study.current.parent?.evaluation?.pv?.length;$('guidedBest').textContent='شاهد البديل';$('guidedTry').disabled=!study.current.parent?.evaluation?.pv?.length;const strip=$('guidedMoves');strip.replaceChildren();for(const [i,r] of rows.entries()){const b=el('button',r.node.parent.fen.split(' ')[5]+(r.side==='w'?'. ':'… ')+r.node.move.san,r.node===study.current?'selected':'');b.onclick=()=>navigate(r.node,{auto:false});b.setAttribute('aria-label','نقلة '+(i+1)+' '+r.node.move.san);if(r.node===study.current)b.setAttribute('aria-current','step');strip.append(b);}const selected=strip.querySelector('.selected');if(selected)strip.scrollLeft=selected.offsetLeft-strip.clientWidth/2;}
$('summaryBtn').onclick=showReviewOverview;$('backToAnalysis').onclick=()=>showView('analysis');$('reviewSettings').onclick=()=>$('settingsDialog').showModal();$('continueAnalysis').onclick=()=>review();$('startGuided').onclick=()=>startGuided();$('guidedBack').onclick=showReviewOverview;$('guidedExit').onclick=()=>{setGuided(false);render();};$('guidedPrev').onclick=()=>{const line=study.mainline(),idx=line.indexOf(study.current);if(idx>1)navigate(line[idx-1],{auto:false});};$('guidedNext').onclick=()=>{const line=study.mainline(),idx=line.indexOf(study.current);if(idx>=line.length-1)showReviewOverview();else navigate(line[Math.max(1,idx+1)],{auto:false});};
