function allStudies(){const items=[];for(const item of library){if(item.id===study.libraryId)continue;try{items.push(Study.restore(item.study))}catch{}}items.push(study);return items;}
function paintSmart(lines){const first=lines[0],wdl=first?.wdl,track=$('wdlTrack');track.classList.toggle('unknown',!wdl);track.querySelectorAll('span').forEach((e,i)=>e.style.width=(wdl?wdl[i]/10:100/3)+'%');$('wdlText').textContent=wdl?'WDL للأبيض · فوز '+(wdl[0]/10).toFixed(1)+'% / تعادل '+(wdl[1]/10).toFixed(1)+'% / خسارة '+(wdl[2]/10).toFixed(1)+'%':'WDL — غير متاح في هذا التقييم؛ أعد تحليل الوضعية';const pressure=alternativeGap(lines,study.current.fen);$('pressureText').textContent=pressure===null?'الحدة — تحتاج بديلين محلّلين بالعمق نفسه':'فارق أفضل بديلين: '+(pressure/100).toFixed(2)+' بيدق · '+(pressure>=150?'حساسة جدًا للاختيار':pressure>=70?'تحتاج دقة':'البديلان متقاربان');const pv=first?.pv;if(pv?.length){try{const c=new Chess(study.current.fen),move=c.move(pv[0]),facts=tacticalFacts({move,fen:c.fen(),parent:study.current}),parts=['الاختيار الأول: '+move.san+'.'];if(move.san.includes('#'))parts.push('تنهي المباراة بكش مات.');else if(move.san.includes('+'))parts.push('تعطي كشًا وتُلزم الخصم برد على تهديد الملك.');if(move.captured)parts.push('تأخذ '+({p:'بيدقًا',n:'حصانًا',b:'فيلًا',r:'رخًا',q:'وزيرًا'}[move.captured]||'قطعة')+'.');if(move.flags.includes('k')||move.flags.includes('q'))parts.push('تُبيّت الملك وتُدخل الرخ إلى اللعب.');if(facts[0])parts.push(facts[0]);if(parts.length===1)parts.push('اختيار المحرك عند عمق '+first.depth+'؛ استكشف الخط لاختبار ردود الخصم.');$('engineCoachText').textContent=parts.join(' ');}catch{$('engineCoachText').textContent='تعذّر تفسير الخط؛ أعد تحليل الوضعية.';}}else $('engineCoachText').textContent='حلّل الوضعية لرؤية اختيار المحرك. الشرح هنا حقائق وقواعد قابلة للفحص، وليس مدرب AI سحابيًا.';}
function previewPV(fen,pv,anchor){try{const c=new Chess(fen);pv.forEach(u=>c.move(u));const box=$('pvPreviewBoard');box.replaceChildren();for(const r of '87654321')for(const f of 'abcdefgh'){const sq=el('span',undefined,(f.charCodeAt(0)+Number(r))%2===0?'dark':'light'),p=c.get(f+r);if(p){const img=el('img');img.src=imgPath(p);img.alt=p.color+p.type;sq.append(img);}box.append(sq);}$('pvPreviewLabel').textContent=pvSAN(fen,pv).at(-1)?.label||'';const tip=$('pvPreview');tip.hidden=false;const rect=anchor.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(window.innerWidth-210,rect.left))+'px';tip.style.top=Math.max(8,Math.min(window.innerHeight-240,rect.bottom+6))+'px';}catch{$('pvPreview').hidden=true;}}
function metricRow(label,rows){const a=aggregate(rows),row=el('div',undefined,'metric-row'),bar=el('div',undefined,'metric-bar'),fill=el('i');fill.style.width=(a.accuracy||0)+'%';bar.append(fill);row.append(el('strong',label),bar,el('span',a.accuracy===null?'—':a.accuracy.toFixed(1)+'%'),el('small',a.done+' / '+a.total+' نقلة'));return row;}
function renderRadar(){const name=$('radarUsername').value;safeStore('radar-name',name);const {rows,games}=collectPerformance(allStudies(),name),a=aggregate(rows);$('radarCoverage').textContent=games.length+' مباراة · '+a.done+' / '+a.total+' نقلة محلّلة';$('radarSummary').replaceChildren();for(const [l,v]of [['المباريات',games.length],['الدقة المحلية',a.accuracy===null?'—':a.accuracy.toFixed(1)+'%'],['الأخطاء',a.mistakes],['نقلات لها وقت',rows.filter(r=>r.seconds!==null).length]]){const e=el('div',l);e.append(el('strong',String(v)));$('radarSummary').append(e);}$('phaseBars').replaceChildren(...[['opening','الافتتاح'],['middle','وسط الدور'],['end','النهايات']].map(([key,label])=>metricRow(label,rows.filter(r=>r.phase===key))));const timed=rows.filter(r=>r.seconds!==null);$('timeMatrix').replaceChildren();if(!timed.length)$('timeMatrix').append(el('p','لا توجد أزمنة صالحة في مباريات هذا اللاعب. استورد PGN يحتوي على [%clk] وTimeControl.','empty'));else for(const [l,min,max] of [['أقل من 5 ثوانٍ',0,5],['5–15 ثانية',5,15],['15–60 ثانية',15,60],['دقيقة فأكثر',60,Infinity]])$('timeMatrix').append(metricRow(l,timed.filter(r=>r.seconds>=min&&r.seconds<max)));const heat=$('mistakeHeatmap'),counts={};rows.filter(r=>['mistake','blunder'].includes(r.key)).forEach(r=>counts[r.node.move.to]=(counts[r.node.move.to]||0)+1);const max=Math.max(1,...Object.values(counts));heat.replaceChildren();for(const rank of '87654321')for(const file of 'abcdefgh'){const key=file+rank,b=el('button',key,counts[key]?'hot':'');b.style.background=counts[key]?'rgba(239,107,101,'+(.2+.7*counts[key]/max)+')':'';b.title=key+' · '+(counts[key]||0)+' أخطاء';b.setAttribute('aria-label',b.title);b.onclick=()=>{const hit=rows.find(r=>r.node.move.to===key&&['mistake','blunder'].includes(r.key));if(hit){loadStudy(hit.study);navigate(hit.node,{auto:false});tab('insight');}};heat.append(b);}$('performanceTimeline').replaceChildren();for(const g of games.slice().sort((a,b)=>a.date.localeCompare(b.date)).slice(-20)){const row=metricRow(g.date,g.rows);row.tabIndex=0;row.setAttribute('role','button');row.onclick=()=>loadStudy(g.study);row.onkeydown=e=>{if(e.key==='Enter')row.click();};$('performanceTimeline').append(row);}if(!games.length)$('performanceTimeline').append(el('p','لا توجد مباريات مطابقة. تحقق من اسم اللاعب، واستورد مبارياتك ثم حلّلها واحفظها.','empty'));}
