function renderRepertoire(){const root=$('repertoireList');root.replaceChildren();if(!repertoires.length)return root.append(el('p','افتح أو أنشئ خطًا على الرقعة، ثم احفظه هنا مع تفرعاته.','empty'));for(const item of repertoires){const row=el('div',undefined,'repertoire-row'),info=el('div'),controls=el('div');info.append(el('strong',item.name),el('small',item.date));const open=el('button','فتح وتعديل'),train=el('button','تدريب الخط','primary'),remove=el('button','حذف'),exportBtn=el('button','PGN');open.onclick=()=>{const s=Study.restore(item.study);s.libraryId=null;loadStudy(s);};train.onclick=()=>{const s=Study.restore(item.study),side=$('repertoireSide').value;practiceQueue=s.mainline().slice(1).filter(n=>n.move.color===side).map(n=>({id:'repertoire-'+crypto.randomUUID(),fen:n.parent.fen,solution:n.move.lan,pv:[n.move.lan],title:item.name+' · تذكّر الخط',due:Date.now(),solved:0,attempts:0,interval:0}));nextPractice();};remove.onclick=()=>{if(!confirm('حذف هذا الافتتاح المحفوظ؟'))return;repertoires=repertoires.filter(x=>x.id!==item.id);safeStore('repertoires',repertoires);renderRepertoire();};exportBtn.onclick=()=>download('repertoire.pgn',Study.restore(item.study).pgn(),'application/x-chess-pgn');controls.append(open,train,exportBtn,remove);row.append(info,controls);root.append(row);}}
$('saveRepertoire').onclick=()=>{if(isLocked()||!study.root.children.length)return say('أنشئ خطًا على الرقعة أولًا.');promptText('اسم الافتتاح',study.headers.Event||'افتتاحي',name=>{if(!name.trim())return;const item={id:crypto.randomUUID(),name:name.trim(),date:new Date().toLocaleDateString('ar-EG'),study:study.serialize()};const old=repertoires.findIndex(x=>x.name===item.name);if(old>=0){if(!confirm('تحديث الافتتاح المحفوظ بنفس الاسم؟'))return;item.id=repertoires[old].id;repertoires[old]=item;}else repertoires.push(item);safeStore('repertoires',repertoires);renderRepertoire();});};
async function combinedExplorer(){const node=study.current,box=$('combinedResults');box.replaceChildren(el('p','جارٍ مقارنة المصادر…'));const own=personalExplorer(allStudies(),node.fen),params=new URLSearchParams({fen:node.fen,moves:'10',topGames:'0',recentGames:'0'}),token=sessionStorage.getItem('tcl-lichess-token');const results=await Promise.allSettled(['masters','lichess'].map(async source=>{const response=await fetch('https://explorer.lichess.org/'+source+'?'+params,{headers:token?{Authorization:'Bearer '+token}:{},signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error(response.status===401?'يتطلب ربط Lichess':'الخدمة غير متاحة ('+response.status+')');return response.json();}));if(study.current!==node)return;box.replaceChildren();const table=el('table'),head=el('tr');['النقلة','الأساتذة','الأونلاين','مبارياتي'].forEach(t=>head.append(el('th',t)));table.append(head);const all=new Map();[...own,...results.flatMap(r=>r.status==='fulfilled'?r.value.moves||[]:[])].forEach(m=>all.set(m.uci,m.san));for(const [uci,san]of all){const tr=el('tr'),td=el('td'),b=el('button',san);b.onclick=()=>playPV([uci]);td.append(b);tr.append(td);for(const list of [...results.map(r=>r.status==='fulfilled'?r.value.moves||[]:null),own]){const m=list?.find(x=>x.uci===uci),cell=el('td',list===null?'—':String(m?(m.total??m.white+m.draws+m.black):0));if(m)cell.title='أبيض '+m.white+' / تعادل '+m.draws+' / أسود '+m.black;tr.append(cell);}table.append(tr);}box.append(table);results.forEach((r,i)=>{if(r.status==='rejected')box.append(el('p',(i?'الأونلاين: ':'الأساتذة: ')+r.reason.message));});if(!all.size)box.append(el('p','لا توجد نتائج لهذا الموقف في المصادر المتاحة.'));if(results.some(r=>r.status==='rejected')&&!token){const b=el('button','ربط Lichess');b.onclick=connectLichess;box.append(b);}box.append(el('p','الأعداد من كل مصدر على حدة وليست مجموعًا موحّدًا. «مبارياتي» تشمل المباريات المحفوظة والدراسة الحالية.','smallprint'));}
