function extractAllMistakes(quiet=false){if(!clinicReady){if(!quiet)say('انتظر فتح قاعدة العيادة.');return;}let added=0;for(const s of allStudies())for(const n of s.mainline().slice(1)){if(!['mistake','blunder'].includes(grade(n)?.key)||!n.parent.evaluation?.pv?.length||puzzles.some(p=>p.fen===n.parent.fen))continue;puzzles.push({id:crypto.randomUUID(),fen:n.parent.fen,solution:n.parent.evaluation.pv[0],pv:n.parent.evaluation.pv,title:(s.headers.White||'الأبيض')+' × '+(s.headers.Black||'الأسود'),sourceMove:n.move.san,created:Date.now(),due:Date.now(),solved:0,attempts:0,interval:0});added++;}safeStore('puzzles',puzzles);renderTraining();if(!quiet)say('أُضيف '+added+' تمرين جديد من المباريات المحلّلة.');}
$('extractPuzzles').onclick=()=>extractAllMistakes();
async function startPuzzle(p){if(whatif||reviewing)return say('أنهِ التجربة أو التحليل أولًا.');clearInterval(clinicInterval);await baseStartPuzzle(p);if(!training)return;const seconds=Math.max(0,Math.min(600,Number($('clinicSeconds').value)||0));let remaining=seconds;$('clinicTimer').textContent=seconds?remaining+' ث':'بلا مؤقّت';if(seconds)clinicInterval=setInterval(()=>{if(!training||training.done){clearInterval(clinicInterval);return;}remaining--;$('clinicTimer').textContent=remaining+' ث';if(remaining<=0){clearInterval(clinicInterval);$('revealBtn').click();$('trainingFeedback').textContent='انتهى الوقت. '+$('trainingFeedback').textContent;}},1000);}
