$('whatifCompare').onclick=async()=>{if(!whatif||busy||!engine.ready)return say('انتظر جاهزية المحرك وأدخل خطك.');const line=study.mainline();if(line.length<2)return say('أدخل نقلة واحدة على الأقل.');const token=++run;reviewing=true;setBusy(true);$('whatifCompare').disabled=true;const opts=settingsValues();try{for(const n of line){const lines=await engine.analyze(n.fen,{...opts,multi:1});if(token!==run)return;n.evaluation=lines[0];n.lines=lines;}$('whatifReport').replaceChildren();const wrong=line.slice(1).find(n=>(grade(n)?.loss||0)>=2);$('whatifReport').append(el('strong',wrong?'أول انخفاض ملحوظ: '+wrong.move.san+' في النقلة '+wrong.parent.fen.split(' ')[5]:'لم يظهر انخفاض بمقدار نقطتين في مؤشر الفرص ضمن الخط والبحث الحالي.'));const expected=$('expectedEval').value.trim(),final=line.at(-1).evaluation;$('whatifReport').append(el('p','توقعك: '+(expected||'لم يُسجّل')+' · تقييم النهاية: '+formatScore(final)));if(expected&&final?.type==='cp')$('whatifReport').append(el('p','الفارق العددي عن توقعك: '+Math.abs(Number(expected)-final.value/100).toFixed(2)+' بيدق (مقياس المحرك).'));for(const n of line.slice(1))$('whatifReport').append(el('p',n.move.san+' · '+(grade(n)?.name||'غير مصنفة')+' · '+formatScore(n.evaluation)));whatif.revealed=true;document.body.classList.remove('whatif-mode');render();say('المقارنة جاهزة. هذه تجربة منفصلة؛ دراستك الأصلية محفوظة.');}catch(e){if(token===run)say(e.message);}finally{if(token===run){reviewing=false;setBusy(false);}$('whatifCompare').disabled=false;}};
