function applyPanelOrder(){const order=readStore('lab-panel-order',[]);if(!Array.isArray(order))return;for(const [i,name]of order.entries()){const panel=document.querySelector('.'+name);if(['engine-panel','notation-panel','whatif-panel'].includes(name)&&panel)panel.style.order=i;}}
let draggedPanel=null;for(const name of ['engine-panel','notation-panel','whatif-panel']){const panel=document.querySelector('.'+name),handle=el('button','⠿ ترتيب اللوحة','panel-drag');handle.draggable=true;handle.title='اسحب لتغيير الترتيب، أو افتح تخصيص المساحة';handle.setAttribute('aria-label','تخصيص ترتيب اللوحة');handle.onclick=()=>$('layoutDialog').showModal();handle.ondragstart=e=>{draggedPanel=panel;e.dataTransfer?.setData('text/plain',name);};handle.ondragend=()=>draggedPanel=null;panel.prepend(handle);panel.ondragover=e=>{if(draggedPanel)e.preventDefault();};panel.ondrop=e=>{if(!draggedPanel||draggedPanel===panel)return;e.preventDefault();const all=[...document.querySelector('.analysisarea').children].sort((a,b)=>(Number(getComputedStyle(a).order)||0)-(Number(getComputedStyle(b).order)||0));const from=all.indexOf(draggedPanel),to=all.indexOf(panel);all.splice(from,1);all.splice(to,0,draggedPanel);safeStore('lab-panel-order',all.map(p=>['engine-panel','notation-panel','whatif-panel'].find(c=>p.classList.contains(c))));applyPanelOrder();};}const saveLayoutHandler=$('saveLayout').onclick;$('saveLayout').onclick=()=>{safeStore('lab-panel-order',[]);document.querySelectorAll('.analysisarea>.lab-panel').forEach(p=>p.style.removeProperty('order'));saveLayoutHandler();};applyPanelOrder();
