function renderUnavailableCategories(){const root=$('categoryRows');for(const [key,name,icon,color] of [['miss','Miss','×','#ff7769']]){const row=el('tr'),label=el('th'),badge=el('span',icon,'grade-badge');badge.style.background=color;label.append(badge,el('span',name));row.append(label);for(let i=0;i<2;i++){const cell=el('td','—');cell.title='غير محسوب: يحتاج تعريفًا وخوارزمية مكتملة';cell.setAttribute('aria-label','غير محسوب');row.append(cell);}if(key==='miss'){const target=[...root.children].find(r=>r.textContent.includes('Blunder'));root.insertBefore(row,target||null);}else if(key==='great')root.insertBefore(row,root.children[1]||null);else root.insertBefore(row,root.firstChild);}}
function renderPhaseComparison(rows){const table=el('table'),head=el('tr');['الإحصاء','الأبيض','الأسود'].forEach(t=>head.append(el('th',t)));table.append(head);const stages=[['الافتتاح',r=>phase(r.node.parent.fen)==='opening'],['وسط الدور',r=>{const pieces=new Chess(r.node.parent.fen).board().flat().filter(p=>p&&!['p','k'].includes(p.type)).length;return pieces>6&&Number(r.node.parent.fen.split(' ')[5])>10;}],['النهايات',r=>new Chess(r.node.parent.fen).board().flat().filter(p=>p&&!['p','k'].includes(p.type)).length<=6],['كش / أخذ / ترقية',r=>!!(r.node.move.captured||r.node.move.promotion||/[+#]/.test(r.node.move.san))]];for(const [name,test]of stages){const tr=el('tr');tr.append(el('th',name));for(const side of ['w','b']){const candidates=rows.filter(r=>r.side===side&&test(r)),done=candidates.filter(r=>r.score!==null),td=el('td',done.length?(done.reduce((a,r)=>a+r.score,0)/done.length).toFixed(1)+'%':'—');td.append(el('small',done.length+' / '+candidates.length+' نقلة'));tr.append(td);}table.append(tr);}$('phaseComparison').replaceChildren(table,el('p','نسب لدقة النقلات في عينات محددة، وليست درجات مستقلة لمهارة التكتيك أو الاستراتيجية.','smallprint'));}
async function syncLatest(manual=false){if(syncBusy)return;if(manual&&(busy||training||whatif))return say('أنهِ التدريب أو التحليل قبل فتح مباراة أخرى.');const username=$('quickUsername').value.trim(),platform=$('quickPlatform').value,key=platform+':'+username;syncBusy=true;$('syncLatest').disabled=true;$('quickSyncStatus').textContent='جارٍ جلب أحدث مباراة منتهية…';try{const raw=await latestFinishedGame(platform,username);if(key!==$('quickPlatform').value+':'+$('quickUsername').value.trim())return;const imported=Study.parse(raw),fingerprint=JSON.stringify([imported.headers.White,imported.headers.Black,imported.headers.Date,imported.mainline().map(n=>n.move?.lan)]);let existing=library.find(item=>{try{const s=Study.restore(item.study);return fingerprint===JSON.stringify([s.headers.White,s.headers.Black,s.headers.Date,s.mainline().map(n=>n.move?.lan)]);}catch{return false;}});const fresh=!existing;if(fresh){imported.libraryId=crypto.randomUUID();existing={id:imported.libraryId,name:imported.headers.White+' × '+imported.headers.Black,folder:'مزامنة '+platform,updated:Date.now(),study:imported.serialize()};library.unshift(existing);safeStore('library',library);$('libraryCount').textContent=library.length;}$('quickSyncStatus').textContent=(fresh?'أُضيفت مباراة جديدة للمكتبة. ':'آخر مباراة موجودة بالفعل. ')+(manual?'':'اضغط «اسحب آخر مباراة» لفتحها دون مقاطعة دراستك.');if(manual&&!busy&&!training&&!whatif){loadStudy(Study.restore(existing.study));say('فُتحت آخر مباراة. اضغط حلّل المباراة لبدء المراجعة.');}if(view==='library')renderLibrary();if(view==='radar')renderRadar();}catch(e){$('quickSyncStatus').textContent=e.message;}finally{syncBusy=false;$('syncLatest').disabled=false;}}
function configureSync(){clearInterval(syncTimer);safeStore('quick-sync',{username:$('quickUsername').value.trim(),platform:$('quickPlatform').value,auto:$('autoSync').checked});if($('autoSync').checked){syncLatest(false);syncTimer=setInterval(()=>{if(document.visibilityState!=='hidden')syncLatest(false);},120000);}}
const syncPrefs=readStore('quick-sync',{});$('quickUsername').value=syncPrefs.username||'Thomas7-77';$('quickPlatform').value=syncPrefs.platform==='lichess'?'lichess':'chesscom';$('autoSync').checked=!!syncPrefs.auto;$('syncLatest').onclick=()=>syncLatest(true);$('quickUsername').onchange=$('quickPlatform').onchange=$('autoSync').onchange=configureSync;configureSync();

// Account -> review summary -> guided studio.
let accountFeed=null,homeLoading=false,homeBulk=false,homeEntries=[];
function renderHomeGames(){const query=$('homeSearch').value.trim().toLowerCase();$('homeGames').replaceChildren();const filtered=homeEntries.filter(s=>[s.headers.White,s.headers.Black,s.headers.Date].join(' ').toLowerCase().includes(query));for(const s of filtered){const h=s.headers,row=el('button',undefined,'home-game');const who=el('strong',(h.White||'White')+' × '+(h.Black||'Black'));who.dir='auto';row.append(who,el('span',(h.Date||'—')+' · '+(h.TimeControl||'—')),el('b',h.Result||'*'),el('span','Game Review →','home-review-link'));row.onclick=()=>selectHomeStudy(s);$('homeGames').append(row);}if(!filtered.length)$('homeGames').append(el('p',query?'لا توجد نتائج في المباريات المحمّلة.':'لا توجد مباريات محمّلة بعد.','empty'));const name=$('homeUsername').value.trim().toLowerCase();let wins=0,losses=0,draws=0;for(const s of homeEntries){const h=s.headers,side=h.White?.toLowerCase()===name?'w':h.Black?.toLowerCase()===name?'b':null;if(!side)continue;if(h.Result==='1/2-1/2')draws++;else if(h.Result===(side==='w'?'1-0':'0-1'))wins++;else if(['1-0','0-1'].includes(h.Result))losses++;}$('homeCount').textContent=homeEntries.length+' مباراة محمّلة · '+wins+' فوز / '+draws+' تعادل / '+losses+' خسارة';}
async function selectHomeStudy(s){if(busy||isLocked())return say('أوقف التحليل الحالي قبل اختيار مباراة.');const saved=library.find(x=>x.id===s.libraryId);loadStudy(Study.restore(saved?saved.study:s.serialize()));saveLibrary();s.libraryId=study.libraryId;await showReviewOverview();if(study.mainline().length<2)return say('الوضعية جاهزة. افتح مساحة التحليل لتحليل FEN.');if(study.mainline().every(n=>n.evaluation))return say('المراجعة المحفوظة جاهزة. اضغط Start Review.');if(engine.ready)await review();else say('المباراة جاهزة. انتظر جاهزية المحرك ثم اضغط «حلّل المباراة».');}
async function loadHomePage(){if(homeLoading||!accountFeed||accountFeed.done)return;homeLoading=true;$('homeFetch').disabled=true;$('homeMore').disabled=true;$('homeAll').disabled=true;$('homePlatform').disabled=$('homeUsername').disabled=true;$('homeStatus').textContent='جارٍ تحميل دفعة من المباريات…';try{const batch=await accountFeed.next();for(const item of batch){try{homeEntries.push(Study.parse(item.pgn));}catch{}}renderHomeGames();$('homeStatus').textContent=accountFeed.done?'اكتمل تحميل الأرشيف المتاح. اختر مباراة لبدء المراجعة.':'اختر مباراة أو حمّل دفعة أقدم.';return true;}catch(e){homeBulk=false;$('homeStatus').textContent=e.message+' يمكنك المحاولة مجددًا.';return false;}finally{homeLoading=false;$('homeFetch').disabled=false;$('homePlatform').disabled=$('homeUsername').disabled=false;$('homeMore').disabled=$('homeAll').disabled=false;$('homeMore').hidden=$('homeAll').hidden=accountFeed.done;}}
$('homeConnect').onsubmit=async e=>{e.preventDefault();if(homeLoading||homeBulk)return;try{accountFeed=new AccountFeed($('homePlatform').value,$('homeUsername').value);}catch(e){$('homeStatus').textContent=e.message;return;}homeEntries=[];renderHomeGames();safeStore('home-account',{platform:accountFeed.platform,username:accountFeed.username});$('homeRatings').replaceChildren();$('homeProfileStatus').textContent='جارٍ تحميل التصنيفات…';$('homeFetch').disabled=true;try{const ratings=await accountFeed.profile();for(const r of ratings){const cell=el('div');cell.append(el('span',r.name),el('strong',String(r.rating)));$('homeRatings').append(cell);}$('homeProfileStatus').textContent='التصنيفات المنشورة على '+(accountFeed.platform==='chesscom'?'Chess.com':'Lichess');}catch(e){$('homeProfileStatus').textContent='تعذر تحميل التصنيفات: '+e.message;}await loadHomePage();$('homeFetch').disabled=false;};
$('homeMore').onclick=loadHomePage;$('homeAll').onclick=async()=>{homeBulk=true;$('homeStop').hidden=false;while(homeBulk&&accountFeed&&!accountFeed.done){if(!await loadHomePage())break;await new Promise(r=>setTimeout(r,300));}homeBulk=false;$('homeStop').hidden=true;};$('homeStop').onclick=()=>{homeBulk=false;$('homeStop').hidden=true;$('homeStatus').textContent='سيتوقف التحميل بعد الدفعة الحالية.';};$('homeSearch').oninput=renderHomeGames;$('homePGN').onclick=()=>{openImport();$('importPGNTab').click();};$('homeRadar').onclick=()=>{$('radarUsername').value=$('homeUsername').value;showView('radar');};$('summaryAnalyze').onclick=review;$('summaryStop').onclick=stopAnalysis;
const homePrefs=readStore('home-account',{});$('homeUsername').value=homePrefs.username||'Thomas7-77';$('homePlatform').value=homePrefs.platform||'chesscom';homeEntries=library.flatMap(x=>{try{return [Study.restore(x.study)]}catch{return []}});renderHomeGames();showView('home');
if(homePrefs.username)$('homeConnect').requestSubmit();
